<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\Theme\Domain\Gateway;

use Civi\Lughauth\Features\Document\Theme\Domain\Theme;

class ThemeCursor
{
    public const string NAME_ASC = 'name';
    public const string NAME_DESC = '-name';

    public function __construct(
        private int $limit,
        private ?string $sinceUid = null,
        private ?string $sinceName = null,
        private ?array $order = null,
    ) {
    }
    public function next(Theme $theme, ?int $size): ThemeCursor
    {
        $next = clone $this;
        $next->sinceUid = $theme->uid();
        $next->sinceName = $theme->getName();
        $next->limit = $size ?? $this->limit;
        return $next;
    }
    public function limit(): int
    {
        return $this->limit;
    }
    public function sinceUid(): ?string
    {
        return $this->sinceUid;
    }
    public function sinceName(): ?string
    {
        return $this->sinceName;
    }
    public function order(): ?array
    {
        return $this->order;
    }
}
